        with open('"'"'/proc/1/environ'"'"', '"'"'rb'"'"') as h:
            for item in h.read().split(b'"'"'\0'"'"'):
                name, _, value = item.decode('"'"'utf-8'"'"', '"'"'surrogateescape'"'"').partition('"'"'='"'"')
